select *
  from TBS011 with (nolock)

select distinct PROSTBA+PROSTBB
  from TBS010 with (nolock)

SELECT PRODES, COUNT(*) AS NumOcorrencias
FROM TBS010 with (nolock)
GROUP BY PRODES
HAVING COUNT(*) > 1

select PRODATCAD
       ,*
  from TBS010 with (nolock)
 where PRODES='VALVULA AGUA DUPLA 127V LCA'

SELECT PRODES, COUNT(*) AS NumOcorrencias
FROM TBS010 with (nolock)
GROUP BY PRODES
HAVING COUNT(*) > 1 
AND SUM(CASE WHEN PRODATCAD = '20240918' THEN 1 ELSE 0 END) > 0

begin tran
update TBS010
   set PROSTATUS='A'
 where PRODATCAD='20240918'

rollback tran
commit tran

begin tran
update TBS010
   set PROUM1='PC'
       ,PROUM1QTD=1
 where PRODATCAD='20240918'

rollback tran
commit tran

begin tran
update TBS010
   set PROSTBA='0'
       ,PROSTBB='41'
 where PRODATCAD='20240918'

rollback tran
commit tran

begin tran
update TBS010
   set PROGERPEN='S'
 where PRODATCAD='20240918'

rollback tran
commit tran

begin tran
update TBS010
   set PROWEB='N'
 where PRODATCAD='20240918'

rollback tran
commit tran

begin tran
update TBS010
   set PROCALPOP='N'
       ,PROCTRLOT='N'
       ,PROCSN='400'
       ,PROINTBAL='N'
       ,PROPESAVEL='N'
       ,PROCTRGRA='N'
       ,PROTARPRE='N'
       ,PRORECACU='N'
       ,PROESTSEGORI='M'
       ,MARCOD=1
       ,MARNOM='COLORMAQ'
 where PRODATCAD='20240918'

rollback tran
commit tran

select max(PROLOGID)
  from TBS010 with (nolock)

select *
  from TBS024 with (nolock)
 where TBSNOM='TBS010'

select *
  from TBS010 with (nolock)
 where PRODATCAD='20240918'

DECLARE @UltimaSequencia INT;

-- Recupera a última sequência gravada
SELECT @UltimaSequencia = MAX(PROLOGID) FROM TBS010;

-- Atualiza os registros sem sequência (PROLOGID = 0) e com data de cadastro igual a '20240918'
WITH CTE_Sequencia AS (
    SELECT PROCOD, 
           ROW_NUMBER() OVER (ORDER BY PROCOD) + @UltimaSequencia AS NovaSequencia
    FROM TBS010
    WHERE PROLOGID = 0
    AND PRODATCAD = '20240918'
)
UPDATE TBS010
SET PROLOGID = CTE_Sequencia.NovaSequencia
FROM CTE_Sequencia
WHERE TBS010.PROCOD = CTE_Sequencia.PROCOD;

SELECT PROLOGID, COUNT(*) AS NumOcorrencias
FROM TBS010 with (nolock)
GROUP BY PROLOGID
HAVING COUNT(*) > 1

